
import 'package:drift/drift.dart';

@DataClassName('CustomerDb')
class Customers extends Table {
  // =====================================================
  // 1. Primary Key & Customer Code
  // =====================================================

  IntColumn get id => integer().autoIncrement()();

  // Internal customer code (e.g. CUS-000001)
  // Generated by application logic, not SQLite.
  TextColumn get customerCode => text()
      .nullable()
      .unique()
      .withLength(max: 30)();

  // =====================================================
  // 2. Customer Type
  // =====================================================

  // individual / company / government
  TextColumn get customerType =>
      text().withDefault(const Constant('individual'))();

  // =====================================================
  // 3. Basic Information
  // =====================================================

  TextColumn get name => text().withLength(
        min: 1,
        max: 150,
      )();

  // Company legal name
  TextColumn get companyName => text()
      .nullable()
      .withLength(max: 200)();

  // Contact person for companies
  TextColumn get contactPerson => text()
      .nullable()
      .withLength(max: 150)();

  // Customer image or company logo
  TextColumn get imagePath => text().nullable()();

  // =====================================================
  // 4. Contact Information
  // =====================================================

  TextColumn get phone => text()
      .nullable()
      .withLength(min: 1, max: 30)();

  TextColumn get secondaryPhone => text()
      .nullable()
      .withLength(max: 30)();

  TextColumn get whatsapp => text()
      .nullable()
      .withLength(max: 30)();

  TextColumn get email => text()
      .nullable()
      .withLength(max: 150)();

  TextColumn get website => text()
      .nullable()
      .withLength(max: 255)();

  // =====================================================
  // 5. Identity & Legal Information
  // =====================================================

  TextColumn get nationalId => text()
      .nullable()
      .withLength(max: 50)();

  TextColumn get taxNumber => text()
      .nullable()
      .withLength(max: 50)();

  TextColumn get commercialRegister => text()
      .nullable()
      .withLength(max: 50)();

  // =====================================================
  // 6. Address Information
  // =====================================================

  // Keep old address field for backward compatibility.
  TextColumn get address => text().nullable()();

  TextColumn get country => text()
      .nullable()
      .withLength(max: 100)();

  TextColumn get city => text()
      .nullable()
      .withLength(max: 100)();

  TextColumn get region => text()
      .nullable()
      .withLength(max: 100)();

  TextColumn get street => text()
      .nullable()
      .withLength(max: 200)();

  TextColumn get buildingNumber => text()
      .nullable()
      .withLength(max: 50)();

  TextColumn get postalCode => text()
      .nullable()
      .withLength(max: 20)();

  // Separate billing and delivery addresses.
  TextColumn get billingAddress => text().nullable()();

  TextColumn get shippingAddress => text().nullable()();

  // =====================================================
  // 7. Customer Classification
  // =====================================================

  // normal / vip / wholesale / retail
  TextColumn get customerCategory =>
      text().withDefault(const Constant('normal'))();

  // retail / wholesale
  TextColumn get priceLevel =>
      text().withDefault(const Constant('retail'))();

  // =====================================================
  // 8. Financial Information
  // =====================================================

  // Whether this customer is allowed to buy on credit.
  BoolColumn get allowCredit =>
      boolean().withDefault(const Constant(false))();

  // Maximum allowed outstanding credit.
  RealColumn get creditLimit =>
      real().withDefault(const Constant(0.0))();

  // Initial balance when migrating an existing customer.
  RealColumn get openingBalance =>
      real().withDefault(const Constant(0.0))();

  // Payment due period in days.
  IntColumn get paymentTermsDays =>
      integer().withDefault(const Constant(0))();

  // Default discount percentage (0 - 100).
  RealColumn get defaultDiscount =>
      real().withDefault(const Constant(0.0))();

  // cash / card / bank_transfer
  TextColumn get preferredPaymentMethod =>
      text().withDefault(const Constant('cash'))();

  // =====================================================
  // 9. Loyalty Program
  // =====================================================

  IntColumn get loyaltyPoints =>
      integer().withDefault(const Constant(0))();

  // =====================================================
  // 10. Customer Activity
  // =====================================================

  DateTimeColumn get lastPurchaseAt => dateTime().nullable()();

  BoolColumn get isActive =>
      boolean().withDefault(const Constant(true))();

  // =====================================================
  // 11. Notes
  // =====================================================

  TextColumn get notes => text().nullable()();

  // =====================================================
  // 12. Timestamps
  // =====================================================

  DateTimeColumn get createdAt =>
      dateTime().withDefault(currentDateAndTime)();

  DateTimeColumn get updatedAt =>
      dateTime().withDefault(currentDateAndTime)();

  // =====================================================
  // Constraints
  // =====================================================

  @override
  Set<Column> get primaryKey => {id};
}
